NACSXN14.ol:
VAR_x := 1.0 - 2.0 * (NCAD4N13.raw * NCAD4N13.raw + NCAD4N14.raw * NCAD4N14.raw);
VAR_y := 2.0 * (NCAD4N15.raw * NCAD4N14.raw + NCAD4N12.raw * NCAD4N13.raw);

if VAR_x > 0 then
return(arctan(VAR_y/VAR_x)*180/3.1415926);
else
		if VAR_x < 0 and VAR_y < 0 then
		return((arctan(VAR_y/VAR_x)-3.1415926)*180/3.1415926);
		else 
		return((arctan(VAR_y/VAR_x)+3.1415926)*180/3.1415926);
		endif;
endif;
